// Authored psychology-specific applications inspired by AIComp, PHSG and UNESCO.
// These are task-design views of existing criteria, never additional competencies or scores.
const L=(de,en)=>({de,en});
const A=(possibleRole,learnerResponsibility,assessmentFocus,exampleTask,relatedCriterionIds)=>({possibleRole:L(...possibleRole),learnerResponsibility:L(...learnerResponsibility),assessmentFocus:L(...assessmentFocus),exampleTask:L(...exampleTask),relatedCriterionIds});
export const aiIntegration={
  P1:A(
    ['KI kann konkurrierende Erklärungen oder Gegenbeispiele zu einem psychologischen Phänomen erzeugen. Menschliche Urteile über KI sind selbst ein Gegenstand psychologischer Erklärung, etwa Automationsvertrauen und Anthropomorphisierung.','AI can generate competing explanations or counterexamples for a psychological phenomenon. Human judgements about AI are also objects of psychological explanation, including automation trust and anthropomorphism.'],
    ['Studierende wählen die Theorie, legen Annahmen offen und erklären Mechanismen selbst. Sie unterscheiden eine sprachlich überzeugende Analogie von einer fachlich tragfähigen Erklärung.','Students choose the theory, state its assumptions and explain the mechanisms themselves. They distinguish a persuasive analogy from a defensible disciplinary explanation.'],
    ['Beurteilt werden Begriffsgenauigkeit, Modellvergleich und Erklärungskraft (P1). Die Belegprüfung einer generierten Behauptung wird bei R4 erfasst.','Assess conceptual accuracy, model comparison and explanatory power (P1). Evaluation of evidence for a generated claim belongs to R4.'],
    ['Erkläre, warum eine Person einer falschen KI-Empfehlung folgt. Vergleiche zwei psychologische Modelle mit einer generierten Erklärung und leite für jedes Modell eine unterscheidbare Vorhersage ab.','Explain why someone follows an incorrect AI recommendation. Compare two psychological models with a generated explanation and derive a distinguishable prediction for each model.'],['P1.1','P1.2','P1.3','R4.2']),
  P2:A(
    ['KI kann Veränderungen von Fallkontexten vorschlagen. Zugleich verändern Empfehlungssysteme, digitale Beziehungen und algorithmische Entscheidungen die Lebensbedingungen, die Psychologie erklären soll.','AI can suggest changes to case contexts. Recommendation systems, digital relationships and algorithmic decisions also reshape the conditions psychology seeks to explain.'],
    ['Studierende prüfen, welche sozialen, kulturellen und entwicklungsbezogenen Annahmen eine Darstellung voraussetzt. Sie erklären Rückwirkungen zwischen Person, System und Institution und vermeiden stereotype Verallgemeinerungen.','Students examine the social, cultural and developmental assumptions behind an account. They explain feedback between people, systems and institutions and avoid stereotyped generalisations.'],
    ['Hier zählt die kontextbezogene Erklärung und ihre Übertragbarkeit (P2). Die normative Bewertung von Benachteiligung gehört zu V1.','The focus is contextual explanation and transferability (P2). Normative judgements about disadvantage belong to V1.'],
    ['Vergleiche zwei fiktive Studierende, die dieselbe KI-Lernhilfe unter unterschiedlichen sprachlichen und sozialen Bedingungen nutzen. Zeichne mögliche Rückwirkungen auf Verhalten, Unterstützung und institutionelle Entscheidungen.','Compare two fictional students using the same AI learning aid under different linguistic and social conditions. Map possible feedback affecting behaviour, support and institutional decisions.'],['P2.1','P2.2','P2.3','V1.1']),
  R1:A(
    ['KI kann Designalternativen, mögliche Störfaktoren und simulierte Szenarien vorschlagen. Ihre Wirkung auf menschliches Verhalten kann selbst Forschungsfrage sein.','AI can suggest design alternatives, possible confounds and simulated scenarios. Its effects on human behaviour can themselves become research questions.'],
    ['Studierende formulieren die Frage und begründen Design, Vergleich und Stichprobe. Simulierte Daten dienen der Planung; sie werden nicht als Beobachtungen realer Personen ausgegeben.','Students formulate the question and justify the design, comparison and sample. Simulated data support planning and must not be represented as observations of real people.'],
    ['Beurteilt wird, ob der Plan die Frage beantworten kann und alternative Erklärungen berücksichtigt (R1). Ethische Zulässigkeit bleibt V1.','Assess whether the design can answer the question and address alternative explanations (R1). Ethical acceptability remains V1.'],
    ['Plane eine Untersuchung dazu, ob KI-Rückmeldung selbständiges Lernen unterstützt. Vergleiche eigene und bereitgestellte KI-Designvorschläge; trenne kurzfristige Leistung von späterem Transfer ohne Hilfe.','Plan an investigation into whether AI feedback supports independent learning. Compare your own and supplied AI design proposals; distinguish immediate performance from later unaided transfer.'],['R1.1','R1.2','R1.3','V1.2']),
  R2:A(
    ['KI kann Itemvarianten oder Kodierungen vorschlagen. KI-basierte Verhaltensindikatoren und automatisierte Bewertungen sind mögliche neue Messverfahren, deren Güte erst belegt werden muss.','AI can suggest item variants or coding schemes. AI-derived behavioural indicators and automated ratings are possible new measurement methods whose quality must be established.'],
    ['Studierende bestimmen das Konstrukt und beurteilen Operationalisierung, Messfehler und Vergleichbarkeit. Plausible Ausgaben gelten nicht automatisch als valide Messung.','Students define the construct and judge operationalisation, measurement error and comparability. Plausible outputs are not automatically valid measurements.'],
    ['Der Nachweis betrifft Messqualität (R2), einschliesslich möglicher Veränderungen bei Modell- oder Populationswechsel. Eine Entscheidung über einen konkreten Fall gehört zu H1.','Evidence concerns measurement quality (R2), including possible changes across models or populations. A decision about a specific case belongs to H1.'],
    ['Entwirf eine Prüfung einer fiktiven KI-Sprachbewertung von Belastung: Welche Vergleichsdaten, Reliabilitäts- und Validitätsbelege sowie Gruppenvergleiche wären erforderlich?','Design an evaluation of a fictional AI language-based measure of distress: which comparison data, reliability and validity evidence, and group comparisons would be needed?'],['R2.1','R2.2','R2.3','H1.2']),
  R3:A(
    ['KI kann Analysecode, Visualisierungen oder erste qualitative Kategorien vorschlagen. Sie kann so die Auswertung beschleunigen, aber auch unbemerkte Analyseentscheidungen vorwegnehmen.','AI can suggest analysis code, visualisations or initial qualitative categories. It may speed up analysis while making analytic decisions that go unnoticed.'],
    ['Studierende wählen und erklären das Verfahren, prüfen Voraussetzungen und führen Kontrollschritte selbst aus. Sie dokumentieren Datenbearbeitung, Änderungen und Unsicherheit.','Students select and explain the method, check assumptions and perform independent checks. They document data preparation, changes and uncertainty.'],
    ['Beurteilt werden nachvollziehbare, methodisch korrekte Auswertung und Interpretation (R3). Die reine Bedienfolge eines Werkzeugs gehört zu T2.3.','Assess transparent, methodologically sound analysis and interpretation (R3). A tool’s operation record alone belongs to T2.3.'],
    ['Überarbeite einen bereitgestellten KI-Analyseentwurf für einen offenen Übungsdatensatz. Begründe Verfahrenswahl und Korrekturen; prüfe ein Ergebnis oder eine qualitative Zuordnung unabhängig vom KI-Vorschlag.','Revise a supplied AI analysis draft for an open practice dataset. Justify the method and corrections; independently check a result or qualitative coding decision.'],['R3.1','R3.2','R3.3','T2.3']),
  R4:A(
    ['KI kann Suchbegriffe, Argumentationsketten oder Gegenpositionen liefern. Generierte Literaturangaben und Synthesen sind zugleich Gegenstand der Prüfung.','AI can suggest search terms, lines of argument or counterpositions. Generated references and syntheses are themselves objects of scrutiny.'],
    ['Studierende suchen Originalbelege, prüfen deren tatsächliche Aussage und revidieren ihr Urteil bei Gegenbelegen. Sie unterscheiden Nachprüfbarkeit, Plausibilität und verbleibende Unsicherheit.','Students locate original evidence, check what it actually says and revise judgements when counterevidence emerges. They distinguish verifiability, plausibility and remaining uncertainty.'],
    ['Für menschliche und generierte Aussagen gelten dieselben Beleganforderungen (R4). Technische Fehlermechanismen zu erklären ist T1; ein zweiter KI-Evaluationswert entfällt.','Human and generated claims face the same evidential standards (R4). Explaining technical failure mechanisms belongs to T1; there is no second AI-evaluation score.'],
    ['Prüfe eine bereitgestellte KI-Zusammenfassung einer psychologischen Kontroverse. Erstelle eine überprüfbare Belegkette, markiere unbelegte Schlüsse und formuliere ein Urteil, das Gegenbefunde berücksichtigt.','Audit a supplied AI summary of a psychological controversy. Build a verifiable evidence chain, mark unsupported inferences and reach a judgement that accounts for conflicting findings.'],['R4.1','R4.2','R4.3','T1.2']),
  H1:A(
    ['KI kann in fiktiven Fällen Informationen ordnen oder diagnostische Alternativen vorschlagen. Ihre Empfehlung kann das menschliche Urteil beeinflussen und zusätzliche Verzerrungen erzeugen.','AI can organise information or suggest assessment alternatives in fictional cases. Its recommendation may influence human judgement and introduce further bias.'],
    ['Studierende begründen die diagnostische Frage, integrieren widersprüchliche Informationen und benennen fehlende Daten sowie eigene Zuständigkeitsgrenzen. Sie prüfen eine Empfehlung anhand des Falls.','Students justify the assessment question, integrate conflicting information and identify missing data and limits to their role. They examine recommendations against the case.'],
    ['Beurteilt wird die begründete Fallinterpretation einschliesslich Unsicherheit (H1). Messqualität bleibt R2, Beziehungsgestaltung K2 und allgemeine Studienkritik R4.','Assess reasoned case interpretation, including uncertainty (H1). Measurement quality remains R2, relationships K2 and general study appraisal R4.'],
    ['Bearbeite eine fiktive Fallvignette zuerst selbst, dann mit einer bereitgestellten KI-Empfehlung. Begründe, was du übernimmst oder verwirfst und welche zusätzliche Information dein Urteil ändern würde.','Assess a fictional vignette independently, then with a supplied AI recommendation. Justify what you retain or reject and identify information that could change your judgement.'],['H1.1','H1.2','H1.3','R2.2']),
  H2:A(
    ['KI kann Varianten einer Präventions-, Beratungs- oder Organisationsmassnahme entwerfen. KI-gestützte Interventionen verändern zugleich Kontakt, Zugang und die Verteilung von Verantwortung.','AI can draft variants of prevention, counselling or organisational interventions. AI-assisted interventions also change contact, access and the distribution of responsibility.'],
    ['Studierende bestimmen das Ziel, erklären den Wirkmechanismus und planen Rückmeldung sowie Anpassung. Sie entwickeln Alternativen, einschliesslich eines Vorgehens ohne KI.','Students define the aim, explain the mechanism and plan feedback and adaptation. They develop alternatives, including an approach without AI.'],
    ['Beurteilt werden die fachliche Passung und der begründete Veränderungsplan (H2). Technische Umsetzung gehört zu T3, ethische Abwägung zu V1.','Assess disciplinary fit and a justified change plan (H2). Technical implementation belongs to T3 and ethical deliberation to V1.'],
    ['Entwirf für einen fiktiven Hochschulkontext zwei Massnahmen zur Lernunterstützung, eine mit und eine ohne KI. Beschreibe Wirkannahmen, mögliche Rückwirkungen und Kriterien für eine spätere Anpassung.','Design two learning-support interventions for a fictional university context, one with and one without AI. Describe mechanisms, possible feedback effects and criteria for later adaptation.'],['H2.1','H2.2','H2.3','T3.1','V1.1']),
  K1:A(
    ['KI kann Text-, Übersetzungs- und Darstellungsvarianten anbieten. Über KI-Einsatz, Unsicherheit und menschliche Verantwortung muss zugleich verständlich mit unterschiedlichen Zielgruppen kommuniziert werden.','AI can offer wording, translation and presentation variants. AI use, uncertainty and human responsibility also need to be communicated clearly to different audiences.'],
    ['Studierende entscheiden, welche Darstellung dem Publikum hilft, prüfen Bedeutungsverschiebungen und überarbeiten auf Rückmeldung. Sie erklären Grenzen und Zuständigkeiten in eigenen Worten.','Students decide which presentation serves the audience, check changes in meaning and revise after feedback. They explain limits and responsibilities in their own words.'],
    ['Hier zählen Verständlichkeit, Struktur und adressatengerechte Überarbeitung (K1). Quellenprüfung gehört zu R4; die Pflicht zur Offenlegung wird unter V1 beurteilt.','The focus is clarity, structure and audience-sensitive revision (K1). Source checking belongs to R4; obligations to disclose are assessed under V1.'],
    ['Erkläre eine fiktive KI-gestützte Forschungsentscheidung für Studierende und für ein Fachteam. Vergleiche eigene und generierte Fassungen; überarbeite sie anhand von Verständnisfragen der beiden Gruppen.','Explain a fictional AI-assisted research decision to students and to a specialist team. Compare your own and generated versions; revise them using comprehension questions from both groups.'],['K1.1','K1.2','K1.3','R4.1','V1.3']),
  K2:A(
    ['KI kann ein Rollenspiel oder alternative Gesprächsverläufe simulieren. Vertrauen, Sorge und unterschiedliche Einstellungen gegenüber KI können selbst Gegenstand eines professionellen Gesprächs sein.','AI can simulate role-play or alternative conversational turns. Trust, concern and differing attitudes towards AI can themselves become topics of professional conversations.'],
    ['Studierende hören zu, klären Anliegen und reagieren auf Ambivalenz. Sie unterscheiden simulierte Antworten von Erleben realer Menschen und erproben Gesprächsführung auch mit menschlichen Gegenübern.','Students listen, clarify concerns and respond to ambivalence. They distinguish simulated responses from real human experience and also practise with human partners.'],
    ['Beurteilt werden Zuhören, gemeinsames Verständnis und Umgang mit Beziehungsspannungen (K2). Ein gelungener Chat belegt keine allgemeine Gesprächs- oder Therapiebefähigung.','Assess listening, shared understanding and responses to relational tension (K2). A successful chat does not establish general conversational or therapeutic competence.'],
    ['Führe ein fiktives Gespräch mit einer Person, die einer KI-Empfehlung misstraut. Übe Nachfragen in einer Simulation und besprich anschliessend mit einer Peerperson, welche Perspektiven die Simulation verfehlt hat.','Conduct a fictional conversation with someone who distrusts an AI recommendation. Practise follow-up questions in a simulation, then discuss with a peer which perspectives the simulation missed.'],['K2.1','K2.2','K2.3']),
  K3:A(
    ['KI kann Teambeiträge zusammenfassen oder Aufgaben vorschlagen. Ihre Verwendung verändert Abstimmung, fachübergreifende Verständigung und Übergaben zwischen Menschen.','AI can summarise team contributions or suggest tasks. Its use changes coordination, interdisciplinary communication and handovers between people.'],
    ['Studierende vereinbaren menschliche Zuständigkeiten, machen Abhängigkeiten sichtbar und bearbeiten unterschiedliche Sichtweisen auf KI-Nutzung. Generierte Vorschläge werden als solche in die gemeinsame Entscheidung eingebracht.','Students agree human responsibilities, make dependencies visible and address differing views on AI use. Generated suggestions enter shared decisions with their origin made clear.'],
    ['Hier zählt die Qualität von Koordination, Übergaben und gemeinsamer Entscheidung (K3). Tool-Bedienung liegt bei T2, technische Schnittstellen bei T3 und zulässige Delegation bei V1.','Assess coordination, handovers and shared decisions (K3). Tool operation belongs to T2, technical interfaces to T3 and permissible delegation to V1.'],
    ['Organisiert im Team ein fiktives Forschungsprojekt mit optionaler KI-Unterstützung. Vereinbart Zuständigkeiten und Übergaben; löst einen Konflikt darüber, ob ein ungeprüfter generierter Beitrag verwendet werden soll.','Organise a fictional team research project with optional AI assistance. Agree responsibilities and handovers; resolve a disagreement about using an unchecked generated contribution.'],['K3.1','K3.2','K3.3','T3.1','V1.2']),
  T1:A(
    ['KI ist hier der technische Gegenstand: Datenflüsse, Modellverhalten, Systemgrenzen und Abhängigkeiten. Auch multimodale und handelnde Systeme werden an stabilen technischen Fragen untersucht.','AI is the technical object here: data flows, model behaviour, system limits and dependencies. Multimodal and action-taking systems are examined through stable technical questions.'],
    ['Studierende erklären relevante Funktionsweisen und leiten daraus Eignung sowie Fehlerbedingungen ab. Sie benennen Wissenslücken bei nicht einsehbaren Systemen.','Students explain relevant mechanisms and infer suitability and failure conditions. They identify knowledge gaps in systems they cannot inspect.'],
    ['Beurteilt wird das technische Verständnis (T1), unabhängig von der Bediengeschwindigkeit. Inhaltliche Wahrheit bleibt R4, Betrieb T2 und eigene Systemgestaltung T3.','Assess technical understanding (T1), independently of operating speed. Substantive truth remains R4, operation T2 and system design T3.'],
    ['Vergleiche eine fiktive lokale Textanalyse mit einem externen multimodalen Assistenten. Zeichne Datenflüsse und erkläre, welche Schlussfolgerungen ihre Ausgaben technisch nicht rechtfertigen.','Compare a fictional local text-analysis tool with an external multimodal assistant. Map data flows and explain which inferences their outputs cannot technically support.'],['T1.1','T1.2','T1.3']),
  T2:A(
    ['Ein vorhandenes digitales oder KI-Werkzeug wird für eine begrenzte Fachaufgabe eingesetzt: passende Eingaben formulieren, Funktionen wählen und Ausgaben technisch sichern.','An existing digital or AI tool is used for a bounded disciplinary task: formulate suitable inputs, select functions and preserve outputs technically.'],
    ['Studierende steuern das Werkzeug bewusst, passen Eingaben an und halten die Bedienfolge nachvollziehbar fest. Sie können bei unpassenden Ergebnissen auf eine andere Vorgehensweise wechseln.','Students operate the tool deliberately, adapt inputs and retain a traceable operation record. They can switch approach when outputs are unsuitable.'],
    ['Beurteilt werden Eingabeübersetzung, gezielte Bedienung und technische Sicherung (T2). Methodische Analysebegründung ist R3; Entwicklung eines neuen Ablaufs ist T3.','Assess task-to-input translation, purposeful operation and technical recording (T2). Analytic reasoning belongs to R3; developing a new workflow belongs to T3.'],
    ['Bearbeite eine psychologische Lernfrage mit einer vorhandenen, bedienbaren lokalen Vorlage. Vorbereitete KI-Ausgaben können darin als Beispiele dienen. Passe Eingaben und Einstellungen an und sichere eine Bedienanleitung mit Beispielausgabe.','Work on a psychology learning question using an existing, operable local template. Prepared AI outputs can serve as examples within it. Adapt inputs and settings and retain operating instructions with a sample output.'],['T2.1','T2.2','T2.3']),
  T3:A(
    ['KI kann Bestandteil eines neu entworfenen Ablaufs sein oder beim Erstellen eines Prototyps helfen. Menschen bestimmen Aufgabenzerlegung, Schnittstellen und kontrollierbare Eingriffe.','AI can be part of a newly designed workflow or assist in prototyping. People determine task decomposition, interfaces and controllable intervention points.'],
    ['Studierende entwerfen die Struktur, verbinden Komponenten und prüfen Ausfälle. Sie können erklären, wann ein System an einen Menschen übergeben oder angehalten werden muss.','Students design the structure, connect components and test failures. They can explain when a system must hand over to a person or stop.'],
    ['Beurteilt werden Entwurf, Integration und Funktionstests (T3). Eine ethische Freigabe wird dadurch nicht nachgewiesen; sie gehört zu V1.','Assess design, integration and functional tests (T3). This does not establish ethical acceptability, which belongs to V1.'],
    ['Entwirf einen kleinen Lernprototyp mit vorbereiteten KI-Antworten, Quellenprüfung durch Menschen und einem Abbruchpfad. Teste fehlende Eingaben, widersprüchliche Ausgaben und eine bewusste menschliche Übersteuerung.','Design a small learning prototype with prepared AI responses, human source checking and a stop path. Test missing inputs, conflicting outputs and deliberate human override.'],['T3.1','T3.2','T3.3','V1.2']),
  V1:A(
    ['KI-Nutzung verändert Schutzinteressen, Autonomie und die Verteilung von Folgen. Auch Machtverhältnisse, Zugang, längerfristige soziale Auswirkungen und Ressourcenverbrauch gehören zur Abwägung.','AI use changes protected interests, autonomy and the distribution of consequences. Power relations, access, longer-term social effects and resource use also inform deliberation.'],
    ['Studierende wägen Nutzen und Risiken aus Sicht betroffener Menschen ab, sichern Einwilligung und Integrität und begründen Grenzen der Delegation. Sie können einen Einsatz auch ablehnen.','Students weigh benefits and risks from affected people’s perspectives, safeguard consent and integrity and justify limits to delegation. They may also decide against use.'],
    ['Beurteilt werden normative Abwägung und verantwortbares Vorgehen (V1). KI-Ethik I–III vertieft dieselbe Kompetenz unter steigenden Anforderungen und schafft keine zusätzliche Kategorie.','Assess ethical deliberation and defensible conduct (V1). AI ethics I–III revisits the same competence at increasing demands and creates no additional category.'],
    ['Entscheide über eine fiktive KI-Lernhilfe, deren Nutzen und Langzeitfolgen unsicher sind. Berücksichtige Studierende mit unterschiedlichen Ressourcen, Datenweitergabe und das Recht auf eine Alternative; dokumentiere Bedingungen und Abbruchgründe.','Decide on a fictional AI learning aid whose benefits and long-term effects are uncertain. Consider students with differing resources, data sharing and access to an alternative; record conditions and reasons to stop.'],['V1.1','V1.2','V1.3']),
  V2:A(
    ['KI kann Rückmeldung, Übungsvarianten und Lernplanung unterstützen. Sie kann zugleich eigene Denkarbeit verdrängen oder ein unbegründetes Gefühl von Verständnis fördern.','AI can support feedback, practice variation and learning plans. It may also displace personal reasoning or create an unwarranted sense of understanding.'],
    ['Studierende setzen eigene Ziele, bestimmen Hilfen und prüfen ihr Verständnis auch ohne KI. Sie passen Strategien anhand tatsächlicher Schwierigkeiten an und holen bei Bedarf Unterstützung.','Students set their own goals, choose support and check understanding without AI as well. They adapt strategies to actual difficulties and seek help when needed.'],
    ['Hier zählt begründete Selbststeuerung anhand von Lernbelegen (V2). Zuversicht bleibt Selbstbericht; die fachliche Richtigkeit einer Lösung wird im jeweiligen Fachkriterium beurteilt.','Assess reasoned self-regulation using learning evidence (V2). Confidence remains self-report; disciplinary correctness is assessed under the relevant criterion.'],
    ['Löse eine Aufgabe zunächst selbst, nutze dann vorbereitete KI-Rückmeldung und bearbeite später eine Transferaufgabe ohne Hilfe. Vergleiche erwartetes und gezeigtes Verständnis und passe deinen Lernplan begründet an.','Attempt a task independently, then use prepared AI feedback and later attempt an unaided transfer task. Compare expected and demonstrated understanding and justify changes to your learning plan.'],['V2.1','V2.2','V2.3'])
};

// A cross-curricular view of the same 16 competencies and 48 criteria.
// Domain rows own references once; edges and examples are navigation, never scores.
const criterionSet = ids => ids.flatMap(id => [1, 2, 3].map(n => `${id}.${n}`));
const domainRow = (domainId, competencyIds, aiRoles, summary, learnerResponsibility, evidenceFocus) => ({
  domainId, competencyIds, criterionIds: criterionSet(competencyIds), aiRoles,
  summary: L(...summary), learnerResponsibility: L(...learnerResponsibility), evidenceFocus: L(...evidenceFocus)
});
const phase = (contextId, title, purpose, learnerAction, assessmentUse) => ({ contextId, title:L(...title), purpose:L(...purpose), learnerAction:L(...learnerAction), assessmentUse:L(...assessmentUse) });
const examplePhase = (contextId, activity, evidence) => ({contextId, activity:L(...activity), evidence:L(...evidence)});
const edge = (fromDomainId, toDomainId, criterionIds, label) => ({fromDomainId,toDomainId,criterionIds,label:L(...label)});
export const aiAcrossCurriculum = {
  schemaVersion: 1, status: 'design-proposal',
  title: L('KI durch alle Kompetenzbereiche denken','Consider AI across every competence domain'),
  principle: L('KI verändert psychologische Fragen, Arbeitsweisen und Folgen. Fachliches Verstehen, wissenschaftliches Prüfen, professionelles Handeln, Zusammenarbeit und Verantwortung behalten ihre eigenen Kriterien. T1–T3 beschreiben den technischen Teil. Alle sechs Bereiche können Aufgaben ohne KI, mit KI oder über KI enthalten.',
    'AI changes psychological questions, working practices and consequences. Disciplinary understanding, scientific scrutiny, professional action, collaboration and responsibility retain their own criteria. T1–T3 describe the technical part. All six domains can include tasks without AI, with AI or about AI.'),
  assessmentNotice: L('Diese Ansicht ordnet Lerngelegenheiten. Sie belegt keine erreichten Kompetenzen. KI-Nutzung, Toolzugang, Quellenanzahl, ECTS und erledigte Spielaufgaben werden nicht als Kompetenznachweis gewertet. Eine Leistung wird anhand des passenden kanonischen Kriteriums beurteilt; die KI- und Future-Skills-Ansichten zählen nichts hinzu.',
    'This view organises learning opportunities. It does not establish attainment. AI use, tool access, source counts, credits and completed game activities are not competence evidence. A performance is assessed against the relevant canonical criterion; AI and future skills views add no further credit.'),
  dimensions: [
    {id:'knowledge',title:L('Wissen und Verstehen','Knowledge and understanding'),description:L('Psychologische Begriffe, Methoden und Befunde mit Wissen über KI und ihren Einsatzbedingungen verbinden. Eine generierte Erklärung muss fachlich begründet werden.','Connect psychological concepts, methods and findings with knowledge of AI and its conditions of use. A generated explanation still needs disciplinary justification.')},
    {id:'skills',title:L('Fähigkeiten und begründetes Handeln','Capabilities and reasoned action'),description:L('Selbst Fragen entwickeln, prüfen, entscheiden, gestalten und verständlich handeln. Welche Hilfe dabei sinnvoll ist, hängt vom Lernziel und vom konkreten Schritt ab.','Develop questions, investigate, decide, design and communicate through personal reasoning. Appropriate support depends on the learning objective and the specific step.')},
    {id:'attitudes',title:L('Haltungen und Selbststeuerung','Attitudes and self-regulation'),description:L('Neugier, begründete Skepsis, Offenheit für Gegenbelege und Bereitschaft zur Korrektur im Handeln zeigen. Selbstauskünfte über Zuversicht sind keine Messung dieser Haltungen.','Show curiosity, reasoned scepticism, openness to counterevidence and willingness to revise through action. Self-reported confidence does not measure these attitudes.')},
    {id:'values',title:L('Werte und Verantwortung','Values and responsibility'),description:L('Autonomie, Integrität, Fairness, Wohlergehen und soziale oder ökologische Folgen bei Entscheidungen berücksichtigen. Bewertet wird eine begründete Abwägung, keine private Gesinnung.','Consider autonomy, integrity, fairness, wellbeing and social or environmental consequences in decisions. Assess reasoned deliberation, not a person’s private convictions.')}
  ],
  domainRows: [
    domainRow('P',['P1','P2'],['tool','subject','context','deliberate-nonuse'],
      ['KI kann Erklärungsalternativen liefern; Vertrauen in Automation, Vermenschlichung von KI und veränderte Lern- oder Lebensbedingungen sind zugleich psychologische Gegenstände.','AI may supply alternative explanations; trust in automation, anthropomorphism and changing learning or living conditions are also psychological subjects.'],
      ['Studierende erklären Mechanismen selbst, unterscheiden konkurrierende Modelle und berücksichtigen Entwicklung sowie sozialen Kontext. Sprachliche Plausibilität ersetzt kein psychologisches Modell.','Students explain mechanisms themselves, distinguish competing models and consider development and social context. Plausible language does not replace a psychological model.'],
      ['P1 prüft die fachliche Erklärung; P2 deren Kontextbezug und Übertragbarkeit. Die Belastbarkeit einer zitierten Studie bleibt bei R4.','P1 addresses the disciplinary explanation; P2 its context and transferability. The strength of a cited study remains under R4.']),
    domainRow('R',['R1','R2','R3','R4'],['tool','subject','context','deliberate-nonuse'],
      ['Forschungsfragen können KI betreffen; KI kann Recherche, Messung und Auswertung unterstützen. Generierte Behauptungen, Instrumente und Analysen werden wissenschaftlich geprüft.','Research may investigate AI; AI can support searching, measurement and analysis. Generated claims, instruments and analyses require scientific scrutiny.'],
      ['Studierende formulieren eine prüfbare Frage, begründen Design und Messung, verstehen ihre Analyse und prüfen Quellen, Schlussfolgerungen und Gegenbelege. Sie benennen, was sich aus den Daten nicht entscheiden lässt.','Students formulate a testable question, justify design and measurement, understand their analysis and examine sources, inferences and counterevidence. They state what the data cannot resolve.'],
      ['R1: Untersuchungsplanung; R2: Messqualität; R3: reproduzierbare Auswertung; R4: Tragfähigkeit von Quellen und Behauptungen. KI-Ausgaben evaluieren gehört je nach Gegenstand hierher, nicht pauschal zu T.','R1: investigation design; R2: measurement quality; R3: reproducible analysis; R4: strength of sources and claims. Evaluating AI output belongs here according to its subject, not automatically under T.']),
    domainRow('H',['H1','H2'],['tool','subject','context','deliberate-nonuse'],
      ['KI kann Fallhypothesen, Interventionsideen oder Gestaltungsvorschläge anbieten. Ihr Einsatz verändert selbst die Bedingungen psychologischer Versorgung, Arbeit und Bildung.','AI may offer case hypotheses, intervention ideas or design proposals. Its use also changes the conditions of psychological care, work and education.'],
      ['Studierende klären den Auftrag, verbinden Fallinformationen, prüfen Alternativen und entwerfen fachlich begründete Veränderungen. Die Entscheidung und ihre Grenzen bleiben menschlich verantwortet.','Students clarify the task, integrate case information, examine alternatives and design changes with disciplinary justification. People remain responsible for decisions and their limits.'],
      ['H1 beurteilt die fallbezogene Schlussfolgerung; H2 Bedarf, Wirkannahmen und Anpassung einer Veränderung. Messgüte bleibt R2, empirische Wirkungsbelege R4, normative Zulässigkeit V1.','H1 addresses the case-specific conclusion; H2 the need, proposed mechanisms and adaptation of change. Measurement quality remains R2, empirical effect evidence R4 and ethical acceptability V1.']),
    domainRow('K',['K1','K2','K3'],['tool','subject','context','deliberate-nonuse'],
      ['KI kann Entwürfe, Übersetzungen und fiktive Gesprächsübungen unterstützen. Menschen müssen ihren Einsatz erklären, Verständigung sichern und gemeinsame Verantwortung organisieren.','AI can support drafting, translation and fictional dialogue practice. People must explain its use, establish shared understanding and organise responsibility together.'],
      ['Studierende hören Menschen zu, reagieren auf Perspektiven und Beziehungsspannungen und machen Entscheidungen für Beteiligte nachvollziehbar. Eine passende Chatbot-Antwort belegt noch keine menschliche Beziehungskompetenz.','Students listen to people, respond to perspectives and relational tensions and make decisions understandable to those involved. A suitable chatbot response does not establish competence in human relationships.'],
      ['K1: verständliche Darstellung; K2: Gespräch und Beziehung; K3: Abstimmung zwischen Menschen. Technische Schnittstellen eines Workflows werden unter T3 beurteilt.','K1: clear presentation; K2: conversation and relationships; K3: coordination between people. Technical workflow interfaces are assessed under T3.']),
    domainRow('T',['T1','T2','T3'],['tool','subject','deliberate-nonuse'],
      ['Technisches Verstehen, gezieltes Bedienen und Systemgestaltung ermöglichen einen kontrollierbaren Einsatz. Modellmechanismen und technische Fehler können auch ohne aktive KI-Nutzung untersucht werden.','Technical understanding, purposeful operation and system design enable controlled use. Model mechanisms and technical failures can also be investigated without actively using AI.'],
      ['Studierende erklären Datenwege und Grenzen, übersetzen Aufgaben in geeignete Eingaben, sichern Bedienabläufe und entwickeln überprüfbare Workflows mit menschlichen Eingriffsmöglichkeiten.','Students explain data flows and limitations, translate tasks into suitable inputs, retain operating records and develop testable workflows with opportunities for human intervention.'],
      ['T1: Funktionsverständnis; T2: Eingabe, Bedienung und technische Sicherung; T3: Komponenten, Schnittstellen und Funktionstests. Fachliche Richtigkeit bleibt im Fachkriterium, Folgenabwägung bei V1.','T1: functional understanding; T2: input, operation and technical records; T3: components, interfaces and functional tests. Disciplinary correctness remains with its disciplinary criterion, consequences with V1.']),
    domainRow('V',['V1','V2'],['tool','subject','context','deliberate-nonuse'],
      ['KI wirft Fragen zu Schutzinteressen, Macht, Zugang und längerfristigen Folgen auf. Sie verändert auch Lernstrategien, Selbstvertrauen und die Verteilung eigener Denkarbeit.','AI raises questions about protected interests, power, access and longer-term consequences. It also changes learning strategies, confidence and the allocation of personal reasoning.'],
      ['Studierende wägen Nutzen, Risiken und Werte ab, begrenzen Delegation und können KI begründet ablehnen. Sie überprüfen ihr Verständnis an eigener Leistung und passen Hilfen sowie Lernstrategien an.','Students weigh benefits, risks and values, limit delegation and may decline AI with justification. They check understanding through their own performance and adapt support and learning strategies.'],
      ['V1: ethische Abwägung und verantwortbares Vorgehen; V2: begründete Selbststeuerung. Vertrauen in die eigenen Fähigkeiten bleibt als Selbstbericht erkennbar; fachliche Leistung wird separat geprüft.','V1: ethical deliberation and defensible conduct; V2: reasoned self-regulation. Confidence in personal capabilities remains visibly self-reported; disciplinary performance is assessed separately.'])
  ],
  flowRule: L('Die Verbindungen zeigen typische Übergänge innerhalb einer Fachaufgabe, keine feste Lernreihenfolge und keine zusätzliche Skala. Wer einer Verbindung folgt, gelangt zum bestehenden Kriterium. Ein Kriterium behält überall dieselbe Bedeutung.',
    'The connections show common transitions within a disciplinary task, not a fixed learning sequence or an additional scale. Following a connection leads to the existing criterion. Each criterion keeps the same meaning throughout.'),
  flowEdges: [
    edge('P','R',['P1.2','R1.1','R4.2'],['Von einer Erklärung zur prüfbaren Frage und zum Gegenbeleg','From an explanation to a testable question and counterevidence']),
    edge('R','H',['R2.2','R4.3','H1.3'],['Mess- und Forschungsbelege in ein begrenztes Fallurteil überführen','Use measurement and research evidence in a bounded case judgement']),
    edge('H','K',['H2.2','K1.2','K2.2'],['Veränderungsvorschläge mit Menschen besprechen','Discuss proposed changes with people']),
    edge('K','T',['K3.2','T3.1','T3.3'],['Menschliche Übergaben und technische Schnittstellen aufeinander abstimmen','Align human handovers and technical interfaces']),
    edge('T','R',['T2.3','T3.3','R3.1','R4.2'],['Funktionsprüfung mit wissenschaftlicher Prüfung verbinden','Connect functional testing with scientific scrutiny']),
    edge('T','V',['T1.3','V1.1','V1.2'],['Technische Möglichkeiten an Folgen und Schutzinteressen prüfen','Consider technical possibilities alongside consequences and protected interests']),
    edge('V','P',['V2.3','P1.3','P2.1'],['Eigenes Verständnis und veränderte Lernbedingungen erneut prüfen','Revisit personal understanding and changing learning conditions']),
    edge('V','H',['V1.2','V1.3','H2.3'],['Verantwortungsgrenzen in die Umsetzung einbauen','Build limits of responsibility into implementation'])
  ],
  phasePolicy: {
    noWholeModuleMandate: true,
    phases: [
      phase('without-ai',['Ohne KI: selbst denken und zeigen','Without AI: reason and demonstrate independently'],
        ['Eigenes Wissen, Lösungsansätze und Urteilsvermögen aufbauen oder unter bekannten Bedingungen beobachten.','Develop personal knowledge, approaches and judgement, or observe them under known conditions.'],
        ['Zum Beispiel zuerst eine Erklärung, Hypothese, Fallformulierung oder Analyseentscheidung selbst erarbeiten; nach einer Hilfsphase eine neue Aufgabe eigenständig lösen. Zulässige nicht-KI-basierte Hilfen werden festgelegt.','For example, first develop an explanation, hypothesis, case formulation or analysis decision independently; after supported practice, solve a new task unaided. Permitted non-AI aids are specified.'],
        ['Ein angekündigter Abschnitt ohne KI kann Eigenleistung sichtbar machen, etwa eine begründete Kurzantwort, Live-Analyse, Transferaufgabe oder mündliche Erläuterung. Er ersetzt keine fachlichen Beurteilungskriterien.','An announced section without AI can make independent work visible, such as a reasoned short answer, live analysis, transfer task or oral explanation. It does not replace disciplinary assessment criteria.']),
      phase('with-ai',['Mit KI: unterstützen, prüfen und entscheiden','With AI: support, check and decide'],
        ['An einer passenden Stelle Unterstützung erproben und den Einfluss auf Ergebnis und eigenes Denken untersuchen.','Try support at an appropriate point and examine its influence on the result and personal reasoning.'],
        ['Einen eigenen Auftrag formulieren, Vorschläge mit fachlichen Kriterien prüfen und die Annahme, Überarbeitung oder Ablehnung begründen. Vorbereitete Ausgaben oder eine lokale Simulation können einen Live-Zugang ersetzen.','Formulate a personal task, scrutinise suggestions using disciplinary criteria and justify accepting, revising or rejecting them. Prepared outputs or a local simulation may replace live access.'],
        ['Beurteilt werden der begründete Umgang mit der Hilfe und die jeweils verlangte Fachleistung. Relevante Ausgaben, menschliche Änderungen und Verantwortlichkeiten müssen nachvollziehbar sein.','Assess the reasoned use of support and the required disciplinary performance. Relevant outputs, human revisions and responsibilities need to be traceable.']),
      phase('about-ai',['Über KI: Mechanismen und Folgen untersuchen','About AI: investigate mechanisms and consequences'],
        ['KI und Mensch-KI-Interaktion als technischen, psychologischen, wissenschaftlichen oder ethischen Gegenstand bearbeiten.','Study AI and human–AI interaction as technical, psychological, scientific or ethical subjects.'],
        ['Zum Beispiel Automationsvertrauen erklären, die Messqualität eines KI-Instruments prüfen oder Verteilungsfolgen abwägen. Das geht auch anhand von Quellen, vorbereiteten Ausgaben und fiktiven Fällen ohne KI-Systemzugang.','For example, explain trust in automation, examine the measurement quality of an AI instrument or weigh distributional consequences. Sources, prepared outputs and fictional cases can support this without access to an AI system.'],
        ['Die Gegenstandswahl erzeugt keine eigene KI-Bewertung. Je nach Frage gelten etwa P1, R2, R4, T1 oder V1; eine einzige Leistung wird nicht doppelt gezählt.','Choosing AI as the subject creates no separate AI assessment. Depending on the question, criteria such as P1, R2, R4, T1 or V1 apply; a single performance is not counted twice.'])
    ],
    assessmentRules: [
      {id:'context-variants',text:L('Kontextangaben an einem Lernziel bezeichnen mögliche Bearbeitungsformen. Dasselbe Ziel kann mit einer vorbereiteten Ausgabe ohne eigenen KI-Zugang oder mit einem Werkzeug bearbeitet werden. Mehrere Kontextetiketten bedeuten weder mehrere erworbene Kompetenzen noch mehrere verpflichtende Prüfungen.','Context labels on an objective indicate possible ways to work on it. The same objective may use a prepared output without personal AI access or an active tool. Several context labels imply neither several acquired competencies nor several compulsory assessments.')},
      {id:'task-specific',text:L('Der erlaubte KI-Einsatz wird für die konkrete Lern- oder Prüfphase begründet. Ein Modul kann mehrere Phasen kombinieren. Diese Entwurfsansicht erklärt kein ganzes Modul pauschal für KI-frei oder KI-pflichtig.','Permitted AI use is justified for the specific learning or assessment phase. A module may combine several phases. This design view does not declare any entire module AI-free or AI-mandatory.')},
      {id:'clear-conditions',text:L('Vor einer beurteilten Leistung müssen Aufgabe, Kriterien, erlaubte Hilfen, Nachweisform und Umgang mit KI-Ausgaben bekannt sein. Verbindliche Prüfbedingungen bleiben Sache der zuständigen Lehr- und Prüfungsverantwortlichen.','Before assessed work, the task, criteria, permitted aids, evidence format and treatment of AI outputs must be clear. Binding assessment conditions remain the responsibility of the relevant teaching and assessment staff.')},
      {id:'independent-transfer',text:L('Eigenständige Denkarbeit wird gezielt aufgebaut und bei Bedarf gesondert beobachtet. Eine später ohne KI gelöste Transferaufgabe kann andere Informationen liefern als ein mit Hilfe entstandenes Produkt; beide werden unter ihren Bedingungen dokumentiert.','Independent reasoning is deliberately developed and, where needed, observed separately. A later transfer task without AI can provide different information from a supported product; both are recorded with their conditions.')},
      {id:'same-criteria',text:L('Die Kriterien bleiben über Phasen hinweg dieselben. Beurteilungen beziehen sich auf konkrete Nachweise und dürfen durch wiederholte Darstellung in KI-, Fach- oder Future-Skills-Ansichten nicht vervielfacht werden.','Criteria remain the same across phases. Assessments refer to specific evidence and must not be multiplied by displaying it in AI, disciplinary or future skills views.')},
      {id:'access-and-support',text:L('Der Entwurf setzt keinen kostenpflichtigen KI-Zugang voraus. Vorbereitete Ausgaben, Simulationen und fachlich gleichwertige Alternativen sind vorzusehen; berechtigte Unterstützungsbedürfnisse werden bei der Festlegung von Bedingungen berücksichtigt.','The proposal requires no paid AI access. Prepared outputs, simulations and equivalent disciplinary alternatives should be available; legitimate support needs are considered when conditions are set.')},
      {id:'no-automated-attainment',text:L('Eine Modellantwort, ein Quellenzähler oder ein abgeschlossener Lerncheck bestätigt keine Kompetenz. Im Spiel bleiben geplante Gelegenheit, Übung, Selbstangabe und tatsächlich beurteilte Leistung getrennt.','A model response, source counter or completed learning check does not establish competence. The game keeps planned opportunities, practice, self-report and actual assessed work distinct.')}
    ]
  },
  examples: [
    {id:'explanation-and-evidence',title:L('Eine überzeugende Erklärung fachlich prüfen','Examine a persuasive explanation'),moduleIds:['200','201','BA'],criterionIds:['P1.2','R4.2','V2.3'],phases:[
      examplePhase('without-ai',['Zwei psychologische Modelle und ihre unterschiedlichen Vorhersagen selbst skizzieren.','Independently outline two psychological models and their differing predictions.'],['Eigene Modellskizze mit einer begründeten Vorhersage.','Personal model outline with a justified prediction.']),
      examplePhase('with-ai',['Eine vorbereitete KI-Erklärung mit der Skizze und einem zugänglichen Originalbefund vergleichen; begründet korrigieren.','Compare a prepared AI explanation with the outline and an accessible original finding; justify revisions.'],['Annotierte Erklärung mit Beleg und begründeter Korrektur.','Annotated explanation with evidence and a justified correction.']),
      examplePhase('about-ai',['Prüfen, ob sprachliche Sicherheit oder ein Autoritätshinweis das eigene Urteil beeinflusst hat; daraus einen nächsten Prüfschritt ableiten.','Examine whether confident wording or an authority cue influenced personal judgement; derive a further check.'],['Kurze Reflexion mit Bezug auf den eigenen Lösungsweg.','Brief reflection tied to the actual reasoning process.'])],assessmentProposal:L('Eine neue Vorhersage ohne KI erläutern; Modellvergleich, Evidenzprüfung und begründete Selbstkorrektur getrennt an P1.2, R4.2 und V2.3 betrachten.','Explain a new prediction without AI; examine model comparison, evidence scrutiny and reasoned self-correction separately through P1.2, R4.2 and V2.3.')},
    {id:'measurement-and-case',title:L('KI-Vorschläge in einem fiktiven diagnostischen Fall','AI suggestions in a fictional assessment case'),moduleIds:['100','501','option:06SM200-511'],criterionIds:['R2.2','H1.2','V1.2'],phases:[
      examplePhase('without-ai',['Messqualität und eine erste Fallhypothese anhand vorgegebener Informationen selbst begründen.','Independently justify measurement quality and an initial case hypothesis using supplied information.'],['Getrennte Notizen zu Messgüte und Fallhypothese.','Separate notes on measurement quality and the case hypothesis.']),
      examplePhase('with-ai',['Eine vorbereitete alternative KI-Fallformulierung prüfen und eine begründete eigene Fassung erstellen.','Examine a prepared alternative AI case formulation and produce a justified personal version.'],['Fallformulierung mit angenommenen und verworfenen Alternativen.','Case formulation with accepted and rejected alternatives.']),
      examplePhase('about-ai',['Abwägen, ob das vorgeschlagene System im fiktiven Setting eingesetzt werden sollte und welche Schutzinteressen betroffen sind.','Weigh whether the proposed system should be used in the fictional setting and which interests require protection.'],['Begründeter Einsatz- oder Verzichtsentscheid.','Justified decision to use or decline the system.'])],assessmentProposal:L('Messgüte, Fallinterpretation und ethische Abwägung unter R2.2, H1.2 und V1.2 trennen. Eine mündliche Begründung ohne KI kann die eigene Urteilsbildung ergänzend sichtbar machen; daraus entsteht keine klinische Qualifikation.','Separate measurement quality, case interpretation and ethical deliberation under R2.2, H1.2 and V1.2. An oral explanation without AI can make personal judgement more visible; it does not create a clinical qualification.')},
    {id:'research-and-workflow',title:L('Einen nachvollziehbaren Forschungsablauf entwickeln','Develop a traceable research workflow'),moduleIds:['102','s03','MA'],criterionIds:['R1.1','R3.1','T3.3','K3.2'],phases:[
      examplePhase('without-ai',['Aus einem offenen Fachproblem eine prüfbare Frage und erste Analyseschritte selbst entwickeln.','Independently develop a testable question and initial analysis steps from an open disciplinary problem.'],['Begründete Frage und eigener Analyseplan.','Justified question and personal analysis plan.']),
      examplePhase('with-ai',['Bei einem ausgewählten Arbeitsschritt Hilfe erproben, Änderungen im Analyseskript sichern und den Ablauf mit fehlerhaften Eingaben testen.','Try support for one selected step, retain changes in the analysis script and test the workflow with faulty inputs.'],['Reproduzierbares Skript und getrenntes Funktionstestprotokoll.','Reproducible script and a separate functional test record.']),
      examplePhase('about-ai',['Im Team erklären, wo ein technischer Erfolg noch keinen wissenschaftlich begründeten Schluss erlaubt.','Explain within the team where technical success still does not permit a scientifically justified conclusion.'],['Nachvollziehbare Übergabe mit offenen Prüfentscheidungen.','Traceable handover with unresolved checking decisions.'])],assessmentProposal:L('Eine neue Analyseentscheidung selbst erläutern. R3.1 bewertet die Reproduzierbarkeit der Analyse; T3.3 die technische Fehlerbehandlung; K3.2 die Verständlichkeit der Übergabe für andere. Die Daten dürfen für die Übung synthetisch sein.','Explain a new analysis decision independently. R3.1 addresses analytic reproducibility; T3.3 technical error handling; K3.2 a traceable handover for others. Practice data may be synthetic.')},
    {id:'relationship-and-reflection',title:L('Gesprächsführung zwischen Simulation und Begegnung','Conversation between simulation and human encounter'),moduleIds:['400','403','600','option:10SMSTS-505'],criterionIds:['K2.1','K2.3','V2.3'],phases:[
      examplePhase('without-ai',['In einer vereinbarten Peer-Übung ein Anliegen mit offenen Fragen klären und das Verstandene rückmelden.','In an agreed peer exercise, clarify a concern through open questions and reflect back understanding.'],['Beobachtete Gesprächssequenz und konkrete Peer-Rückmeldung.','Observed conversational sequence and specific peer feedback.']),
      examplePhase('with-ai',['Ein fiktives Gespräch oder vorbereitete KI-Rückmeldung nutzen, um eine eigene Formulierung zu überarbeiten.','Use a fictional conversation or prepared AI feedback to revise a personal formulation.'],['Begründete Überarbeitung mit Bezug auf den eigenen Wortlaut.','Justified revision tied to the student’s actual wording.']),
      examplePhase('about-ai',['Grenzen der Simulation und Unterschiede zur Reaktion eines Menschen benennen; ein persönliches Übungsziel ableiten.','Identify simulation limits and differences from a person’s response; derive a personal practice goal.'],['Reflexion zu beobachteten Grenzen und nächstem Übungsschritt.','Reflection on observed limits and the next practice step.'])],assessmentProposal:L('Eine weitere Peer-Sequenz ohne KI an K2.1 und K2.3 beobachten. V2.3 betrachtet die begründete Anpassung des Lernens. Das KI-Rollenspiel allein bestätigt keine menschliche Beziehungskompetenz.','Observe another peer sequence without AI through K2.1 and K2.3. V2.3 concerns reasoned adaptation of learning. AI role-play alone does not establish competence in human relationships.')}
  ]
};
